import json, math
from itertools import combinations

def covers(S, n):
    d = set()
    for a in S:
        for b in S:
            d.add((a - b) % n)
    return len(d) == n

def f_brute(n):
    for k in range(1, n + 1):
        for c in combinations(range(1, n), k - 1):
            if covers((0,) + c, n):
                return k
    return n

def construct(n):
    m = math.isqrt(n - 1) + 1
    S = set(range(m)) | {(m * j) % n for j in range(m + 1)}
    return S

brute = {n: f_brute(n) for n in range(2, 25)}

# check lower bound k(k-1) >= n-1 on brute-force values
lb_ok = all(k * (k - 1) >= n - 1 for n, k in brute.items())

# verify upper-bound construction and size ~ 2 sqrt n
cons_ok = True
for n in list(range(2, 400)) + [1000, 2500, 5000]:
    S = construct(n)
    if not covers(S, n):
        cons_ok = False
        break

# exponent bounds at huge n
N = 10**24
lower = math.isqrt(N - 1)
upper = 2 * (math.isqrt(N - 1) + 1) + 1
r_low = math.log(lower) / math.log(N)
r_up = math.log(upper) / math.log(N)

if lb_ok and cons_ok and abs(r_low - 0.5) < 0.01 and abs(r_up - 0.5) < 0.01:
    ans = "1/2"
else:
    ans = "UNSUPPORTED"

print(json.dumps({
    "final_answer": ans,
    "evidence": {
        "brute_f": brute,
        "lower_bound_k(k-1)>=n-1_holds": lb_ok,
        "construction_covers_tested": cons_ok,
        "ratio_lower_at_1e24": r_low,
        "ratio_upper_at_1e24": r_up
    }
}, separators=(",", ":")))
